/**
 * execute-artifacts.mjs — Scan for HTML artifacts generated by visual-explainer skill.
 *
 * Claude Code's visual-explainer skill writes self-contained HTML files to
 * ~/.agent/diagrams/. After each mission run, we scan for files created
 * during the run window and record them as artifacts.
 *
 * Artifacts are stored in .execute-runs/<run>/.artifacts.json and also
 * indexed in .execute-artifacts.json (project-level, gitignored).
 */

import fs from "node:fs/promises";
import path from "node:path";
import os from "node:os";

import { projectRoot } from "./execute-worker-state.mjs";

// Where visual-explainer writes HTML files
export const DIAGRAMS_DIR = path.join(os.homedir(), ".agent", "diagrams");

// Project-level artifact index (gitignored)
export const ARTIFACTS_INDEX_FILE = path.join(projectRoot, ".execute-artifacts.json");

/**
 * Scan ~/.agent/diagrams/ for HTML files created during a mission run.
 * Uses mtime to find files newer than runStartedAt (or last 5 minutes if not given).
 *
 * @param {object} options
 * @param {number} options.issueNumber
 * @param {string} options.runDir — path to the mission run directory
 * @param {string} options.runtimeId
 * @param {Date}   [options.since] — only return files created after this date
 * @returns {Promise<Artifact[]>} array of artifact records
 */
export async function scanRunArtifacts({
  issueNumber = null,
  runDir = null,
  runtimeId = null,
  since = null
} = {}) {
  // Determine time window: use runDir mtime as "mission started" marker
  let sinceMs;
  if (since instanceof Date) {
    sinceMs = since.getTime();
  } else if (runDir) {
    try {
      const stat = await fs.stat(runDir);
      // Run dir was created just before mission launched — use its birthtime
      sinceMs = (stat.birthtimeMs || stat.ctimeMs) - 5000; // 5s grace
    } catch {
      sinceMs = Date.now() - 5 * 60 * 1000; // fallback: last 5 min
    }
  } else {
    sinceMs = Date.now() - 5 * 60 * 1000;
  }

  let entries;
  try {
    entries = await fs.readdir(DIAGRAMS_DIR, { withFileTypes: true });
  } catch (err) {
    if (err?.code === "ENOENT") return [];
    throw err;
  }

  const artifacts = [];
  for (const entry of entries) {
    if (!entry.isFile()) continue;
    if (!entry.name.endsWith(".html")) continue;

    const filePath = path.join(DIAGRAMS_DIR, entry.name);
    try {
      const stat = await fs.stat(filePath);
      const fileMs = stat.mtimeMs;
      if (fileMs < sinceMs) continue;

      artifacts.push({
        filename: entry.name,
        filePath,
        issueNumber: issueNumber ?? null,
        runtimeId: runtimeId ?? null,
        createdAt: new Date(fileMs).toISOString(),
        size: stat.size
      });
    } catch {
      // File disappeared — skip
    }
  }

  // Sort chronologically
  artifacts.sort((a, b) => new Date(a.createdAt) - new Date(b.createdAt));

  // Persist artifacts to run dir + global index
  if (artifacts.length > 0) {
    if (runDir) {
      await fs.writeFile(
        path.join(runDir, ".artifacts.json"),
        `${JSON.stringify(artifacts, null, 2)}\n`,
        "utf8"
      ).catch(() => {});
    }
    await appendArtifactsToIndex(artifacts).catch(() => {});
  }

  return artifacts;
}

/**
 * Append new artifacts to the project-level index file.
 * Deduplicates by filePath.
 */
async function appendArtifactsToIndex(newArtifacts) {
  let existing = [];
  try {
    const text = await fs.readFile(ARTIFACTS_INDEX_FILE, "utf8");
    const parsed = JSON.parse(text);
    if (Array.isArray(parsed)) existing = parsed;
  } catch { /* ok */ }

  const existingPaths = new Set(existing.map(a => a.filePath));
  const toAdd = newArtifacts.filter(a => !existingPaths.has(a.filePath));
  if (toAdd.length === 0) return;

  const merged = [...existing, ...toAdd];
  await fs.writeFile(
    ARTIFACTS_INDEX_FILE,
    `${JSON.stringify(merged, null, 2)}\n`,
    "utf8"
  );
}

/**
 * Read all artifacts from the project-level index, optionally filtered by issueNumber.
 *
 * @param {object} [options]
 * @param {number} [options.issueNumber] — filter to a specific issue
 * @returns {Promise<Artifact[]>}
 */
export async function readArtifacts({ issueNumber = null } = {}) {
  let all = [];
  try {
    const text = await fs.readFile(ARTIFACTS_INDEX_FILE, "utf8");
    const parsed = JSON.parse(text);
    if (Array.isArray(parsed)) all = parsed;
  } catch (err) {
    if (err?.code === "ENOENT") return [];
    throw err;
  }

  if (issueNumber !== null) {
    return all.filter(a => a.issueNumber === issueNumber);
  }
  return all;
}

/**
 * Serve an artifact file: read and return its content + metadata.
 * Returns null if the file doesn't exist in the index or on disk.
 *
 * @param {string} filename
 * @returns {Promise<{ content: Buffer, contentType: string, filename: string } | null>}
 */
export async function readArtifactFile(filename) {
  // Sanitise: only allow .html files, no path traversal
  const safe = path.basename(filename);
  if (!safe.endsWith(".html") || safe !== filename) return null;

  const filePath = path.join(DIAGRAMS_DIR, safe);
  try {
    const content = await fs.readFile(filePath);
    return { content, contentType: "text/html; charset=utf-8", filename: safe };
  } catch {
    return null;
  }
}
